let tracks = [];
let totalNotes = 0;
for(let i = 0; i < json.tracks.length; i++) {
    let track = json.tracks[i].notes;
    tracks[i] = [];
    for(let k = 0; k < track.length; k++) {
        tracks[i].push({
            note: track[k].name,
            time: track[k].time,
        });
    }
    totalNotes += k;
}
time = millis() - time;
let x = random(0, 1);
println('Done! (Took ' + time + 'ms to parse ' + totalNotes + ' total notes)');
println('TRACK STATS: ');
println(tracks.length + ' tracks total');
for(let i = 0 ; i < tracks.length; i++) {
    println('Track ' + i + ': ' + tracks[i].length + ' notes | ' + round(tracks[i][tracks[i].length - 1].time) + ' total seconds of playtime (from last note)');

}

function keyPressed () {
    println('let tracks = [');
    for(let i = 0; i < tracks.length; i++) {
        let track = tracks[i];
        let trackStr = '[';
        for(let k = 0; k < track.length; k++) {
            trackStr += '{note: "' + track[i].note + '" , time: ' + track[i].time + '},'
        }
        trackStr += '], ';
        println(trackStr);
    }
    
}
